  console.error('Redis error:', err);
});

client.on('ready', () => {
  console.log('Redis client ready');
});
```

### Step 4: Define Game State Snapshot Functions

Define functions to save and retrieve game state snapshots from Redis:

```javascript
async function saveGameStateSnapshot(snapshotId, gameState) {
  const snapshotKey = `gameState:${snapshotId}`;
  await client.set(snapshotKey, JSON.stringify(gameState));
  console.log(`Saved game state snapshot ${snapshotId}`);
}

async function getGameStateSnapshot(snapshotId) {
  const snapshotKey = `gameState:${snapshotId}`;
  const snapshot = await client.get(snapshotKey);
  if (snapshot) {
    return JSON.parse(snapshot);
  }
  return null;
}
```

### Step 5: Integrate with Game Logic

Integrate the caching logic into your game's main loop or wherever you manage game state:

```javascript
