  { id: 2, username: 'moderator1', role: 'moderator' },
  { id: 3, username: 'admin1', role: 'admin' }
];

// Mock authentication middleware
const authenticate = (req, res, next) => {
  const user = users.find(u => u.username === req.headers.authorization);
  if (!user) {
    return res.status(401).send('Unauthorized');
  }
  req.user = user;
  next();
};

// Example routes
app.get('/game', authenticate, checkPermission(['view_game']), (req, res) => {
  res.send('Viewing game');
});

app.post('/game/play', authenticate, checkPermission(['play_game']), (req, res) => {
  res.send('Playing game');
});

app.post('/users/manage', authenticate, checkPermission(['manage_users']), (req, res) => {
  res.send('Managing users');
});

app.post('/content/manage', authenticate, checkPermission(['manage_content']), (req, res) => {
  res.send('Managing content');
});

app.post('/administrate', authenticate, checkPermission(['administrate']), (req, res) => {
  res.send('Administering game');
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
