```javascript
const jwt = require('jsonwebtoken');
const redis = require('redis');

// Create a single Redis client instance
const redisClient = redis.createClient({
  url: 'redis://localhost:6379' // Adjust URL as needed
});

redisClient.on('error', (err) => console.error('Redis error:', err));

const tokenExpiry = 3600; // 1 hour

const generateToken = (user) => {
  const token = jwt.sign(user, process.env.SECRET_KEY, { expiresIn: tokenExpiry });
  return token;
};

const storeRefreshToken = (userId, refreshToken) => {
  redisClient.set(`refresh_token:${userId}`, refreshToken, 'EX', tokenExpiry * 2); // Store refresh token for twice the duration of access token
};

const verifyToken = (token) => {
  try {
    const decoded = jwt.verify(token, process.env.SECRET_KEY);
    return decoded;
  } catch (err) {
    console.error('JWT verification error:', err);
    return null;
  }
