    redisClient.get(`refresh_token:${userId}`, (err, storedToken) => {
      if (err) {
        reject(err);
      } else if (storedToken === refreshToken) {
        resolve(true);
      } else {
        resolve(false);
      }
    });
  });
};

module.exports = {
  generateToken,
  storeRefreshToken,
  verifyToken,
  validateRefreshToken
};
```

### Key Changes:
