```javascript
const redis = require('redis');
const crypto = require('crypto');
const client = redis.createClient();

const TOKEN_TTL = 24 * 60 * 60; // 24 hours
const REVOKED_TOKEN_KEY_PREFIX = 'revoked_token:';
const VALID_TOKEN_KEY_PREFIX = 'valid_token:';

const rotateRefreshToken = async (oldToken) => {
  try {
    // Check if token is revoked
    const isRevoked = await client.exists(`${REVOKED_TOKEN_KEY_PREFIX}${oldToken}`);
    if (isRevoked) {
      throw new Error('Token is revoked');
    }

    // Generate new refresh token
    const newToken = generateRefreshToken();

    // Store new token in Redis
    await client.set(`${VALID_TOKEN_KEY_PREFIX}${newToken}`, 'valid', 'EX', TOKEN_TTL);

    // Revoke old token
    await client.multi()
      .set(`${REVOKED_TOKEN_KEY_PREFIX}${oldToken}`, 'revoked', 'EX', TOKEN_TTL)
      .del(`${VALID_TOKEN_KEY_PREFIX}${oldToken}`)
      .exec();

    return newToken;
  } catch (error) {
    console.error('Error rotating refresh token:', error);
    throw error;
  }
};

const generateRefreshToken = () => {
  // Generate a cryptographically secure random token
  return crypto.randomBytes(32).toString('hex');
};

// Example usage
rotateRefreshToken('old_token')
  .then(newToken => console.log('New token:', newToken))
  .catch(error => console.error('Failed to rotate token:', error));
```

### Explanation

1. **Secure Token Generation**:
   - Use `crypto.randomBytes` to generate a cryptographically secure random token.
   - The token length is 32 bytes (64 characters in hexadecimal), which is sufficiently long.

2. **Proper Token Revocation**:
   - Use a dedicated key prefix (`REVOKED_TOKEN_KEY_PREFIX`) for revoked tokens.
   - Use Redis transactions (`multi`) to ensure that revoking the old token and deleting the valid token entry are atomic.

3. **Efficient Redis Usage**:
   - Use `exists` to check if a token is revoked.
   - Use `set` with `EX` to set an expiration time.
   - Use `del` to remove the valid token entry.

4. **Error Handling and Logging**:
   - Log errors for debugging and auditing.
   - Rethrow errors to propagate them to the caller.

5. **Expiration Handling**:
   - Set an expiration time for both valid and revoked tokens to ensure they are cleaned up after 24 hours.

By following these improvements, your refresh token rotation mechanism will be more secure and efficient. If you have any specific requirements or additional questions, feel free to ask!

