Certainly! Implementing refresh token rotation is a crucial aspect of securing your application. Here's a step-by-step guide on how to implement refresh token rotation using Redis:

### Step 1: Generate Access and Refresh Tokens

When a user logs in, generate both an access token and a refresh token. Store the refresh token in Redis with an appropriate expiration time.

### Step 2: Store Refresh Tokens in Redis

Store the refresh token in Redis with a unique identifier (e.g., the user ID) and set an expiration time.

### Step 3: Rotate Refresh Tokens

When a user requests a new access token using a refresh token, generate a new refresh token and replace the old one in Redis.

### Step 4: Invalidate Old Refresh Tokens

Ensure that the old refresh token is invalidated once a new one is issued.

### Example Implementation

Here's a complete example of how you can implement these steps using Express.js and Redis:

```javascript
const express = require('express');
const redis = require('redis');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('./models/User'); // Assuming you have a User model

const app = express();
const client = redis.createClient();

// Middleware to connect to Redis
client.on('ready', () => {
  console.log('Redis client is ready');
});

client.on('error', (err) => {
  console.error('Redis client error:', err);
});

// Function to generate JWT tokens
const generateTokens = (userId) => {
  const accessToken = jwt.sign({ userId }, 'your_jwt_secret', { expiresIn: '15m' });
  const refreshToken = jwt.sign({ userId }, 'your_jwt_refresh_secret', { expiresIn: '7d' });
  return { accessToken, refreshToken };
};

// Function to authenticate user
const authenticateUser = async (username, password) => {
  const user = await User.findOne({ username });
  if (!user || !(await user.comparePassword(password))) {
    throw new Error('Invalid username or password');
  }
  return user;
};

// Function to save refresh token in Redis
const saveRefreshToken = async (userId, refreshToken) => {
  await client.set(`refreshToken:${userId}`, refreshToken, 'EX', 7 * 24 * 60 * 60);
};

// Function to get refresh token from Redis
const getRefreshToken = async (userId) => {
  return await client.get(`refreshToken:${userId}`);
};

// Function to delete refresh token from Redis
const deleteRefreshToken = async (userId) => {
  await client.del(`refreshToken:${userId}`);
};

// Login route
app.post('/login', async (req, res) => {
  const { username, password } = req.body;

  try {
    const user = await authenticateUser(username, password);
    const { accessToken, refreshToken } = generateTokens(user.id);
    await saveRefreshToken(user.id, refreshToken);
    res.json({ accessToken, refreshToken });
  } catch (error) {
    res.status(401).json({ message: 'Invalid username or password' });
  }
});

// Refresh token route
app.post('/refresh', async (req, res) => {
  const { refreshToken } = req.body;

  try {
    const decoded = jwt.verify(refreshToken, 'your_jwt_refresh_secret');
    const userId = decoded.userId;
    const storedRefreshToken = await getRefreshToken(userId);

    if (!storedRefreshToken || storedRefreshToken !== refreshToken) {
      throw new Error('Invalid refresh token');
    }

    const { accessToken, newRefreshToken } = generateTokens(userId);
    await deleteRefreshToken(userId);
    await saveRefreshToken(userId, newRefreshToken);

    res.json({ accessToken, refreshToken: newRefreshToken });
  } catch (error) {
    res.status(401).json({ message: 'Invalid refresh token' });
  }
});

// Example protected route
app.get('/protected', authenticateToken, async (req, res) => {
  res.json({ message: 'Access granted' });
});

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.sendStatus(401);
  }

  jwt.verify(token, 'your_jwt_secret', (err, user) => {
    if (err) {
      return res.sendStatus(403);
    }
    req.user = user;
    next();
  });
}

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

### Explanation

1. **Generate Tokens**:
   - `generateTokens` generates both an access token and a refresh token.

2. **Authenticate User**:
   - `authenticateUser` verifies the user's credentials.

3. **Save Refresh Token**:
   - `saveRefreshToken` stores the refresh token in Redis with an expiration time.

4. **Get Refresh Token**:
   - `getRefreshToken` retrieves the refresh token from Redis.

5. **Delete Refresh Token**:
   - `deleteRefreshToken` deletes the refresh token from Redis.

6. **Login Route**:
   - Handles user login, generates tokens, and saves the refresh token in Redis.

7. **Refresh Token Route**:
   - Handles refreshing the access token, rotates the refresh token, and updates Redis.

8. **Protected Route**:
   - Protects routes using the `authenticateToken` middleware.

