Implementing a system to automatically rotate refresh tokens every 24 hours involves several steps, including generating new tokens, storing them securely, and scheduling the rotation. Here's a comprehensive guide to help you set up this system using the `jsonwebtoken` library and a scheduling mechanism like `node-cron`.

### Step 1: Generate and Store Tokens

First, ensure you have a mechanism to generate and store access and refresh tokens. You can use the `jsonwebtoken` library to create these tokens.

#### Install Required Packages

```bash
npm install jsonwebtoken node-cron
```

### Step 2: Generate Access and Refresh Tokens

Create functions to generate access and refresh tokens.

#### `src/auth.js`

```javascript
const jwt = require('jsonwebtoken');
const config = require('./config');

const generateAccessToken = (userId) => {
  return jwt.sign({ userId }, config.ACCESS_TOKEN_SECRET, { expiresIn: '15m' });
};

const generateRefreshToken = (userId) => {
  return jwt.sign({ userId }, config.REFRESH_TOKEN_SECRET, { expiresIn: '24h' });
};

module.exports = {
  generateAccessToken,
  generateRefreshToken,
};
```

### Step 3: Store Tokens Securely

Store the refresh tokens securely, typically in a database or a secure cache like Redis.

#### `src/db.js`

```javascript
const redis = require('redis');
const client = redis.createClient();

client.on('error', (err) => {
  console.error('Redis error:', err);
});

module.exports = client;
```

### Step 4: Schedule Token Rotation

Use `node-cron` to schedule the token rotation every 24 hours.

#### `src/scheduleTokenRotation.js`

```javascript
const cron = require('node-cron');
const db = require('./db');
const { generateRefreshToken } = require('./auth');
const config = require('./config');

cron.schedule('0 0 * * *', () => {
  // Fetch all users who need token rotation
  db.keys('refresh_token:*', (err, keys) => {
    if (err) {
      console.error('Error fetching keys:', err);
      return;
    }

    keys.forEach((key) => {
      const userId = key.split(':')[1];
      const newRefreshToken = generateRefreshToken(userId);

      db.set(key, newRefreshToken, 'EX', 86400, (err) => {
        if (err) {
          console.error('Error setting refresh token:', err);
        } else {
          console.log(`Refresh token rotated for user ${userId}`);
        }
      });
    });
  });
});

console.log('Scheduled token rotation every 24 hours');
```

### Step 5: Initialize the Scheduler

Ensure the scheduler runs when your application starts.

#### `src/index.js`

```javascript
require('./scheduleTokenRotation');
```

### Step 6: Configuration

Define your configuration constants for secrets and other settings.

#### `src/config.js`

```javascript
module.exports = {
  ACCESS_TOKEN_SECRET: 'your_access_token_secret',
  REFRESH_TOKEN_SECRET: 'your_refresh_token_secret',
};
```

### Step 7: Handle Token Expiry and Rotation

Ensure your authentication middleware handles token expiry and rotates refresh tokens as needed.

#### `src/middleware/authMiddleware.js`

```javascript
const jwt = require('jsonwebtoken');
const db = require('./db');
const { generateAccessToken, generateRefreshToken } = require('./auth');
const config = require('./config');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, config.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      // Check if the error is due to expired token
      if (err.name === 'TokenExpiredError') {
        const refreshTokenKey = `refresh_token:${user.userId}`;
        db.get(refreshTokenKey, (err, refreshToken) => {
          if (err || !refreshToken) {
            return res.status(401).json({ message: 'Invalid refresh token' });
          }

          jwt.verify(refreshToken, config.REFRESH_TOKEN_SECRET, (err, user) => {
            if (err) {
              return res.status(401).json({ message: 'Invalid refresh token' });
            }

            const newAccessToken = generateAccessToken(user.userId);
            const newRefreshToken = generateRefreshToken(user.userId);

            db.set(refreshTokenKey, newRefreshToken, 'EX', 86400, (err) => {
              if (err) {
                console.error('Error setting refresh token:', err);
              }
            });

            res.json({ accessToken: newAccessToken, refreshToken: newRefreshToken });
          });
        });
      } else {
        return res.sendStatus(403);
      }
    }

    req.user = user;
    next();
  });
};

module.exports = authenticateToken;
```

### Conclusion

By following these steps, you can implement a system to automatically rotate refresh tokens every 24 hours. This ensures that your tokens remain secure and reduces the risk of unauthorized access. The key components are generating and storing tokens securely, scheduling token rotations, and handling token expiry and rotation in your middleware.

