import Matter from 'matter-js';

const engine = Matter.Engine.create();
const world = engine.world;

// Example bodies
const ball = Matter.Bodies.circle(400, 100, 50);
const box = Matter.Bodies.rectangle(400, 200, 100, 50, { isStatic: true });

Matter.World.add(world, [ball, box]);

// List of bodies for reference
const bodies = [ball, box];

function updatePhysics() {
  Matter.Engine.update(engine, 1000 / 60);

  // Example of handling collisions and updating game state
  const pairs = Matter.Collision.pairs(world.bodies);
  pairs.forEach(pair => {
    const bodyA = pair.bodyA;
    const bodyB = pair.bodyB;

    if (bodyA && bodyB) {
      console.log(`Collision detected between ${bodyA.id} and ${bodyB.id}`);
      console.log(`Body A position: ${bodyA.position.x}, ${bodyA.position.y}`);
      console.log(`Body B position: ${bodyB.position.x}, ${bodyB.position.y}`);
    } else {
      console.error('One or both bodies are undefined');
    }
  });

  // Example of removing a body
  if (shouldRemoveBody(ball)) {
    removeBody(ball);
  }
}

function shouldRemoveBody(body) {
  // Define your condition for removing the body
  return body.position.y > 500;
}

function removeBody(body) {
  // Remove the body from the physics world
  Matter.World.remove(world, body);

  // Update the list of bodies
  bodies.splice(bodies.indexOf(body), 1);

  console.log(`Removed body with ID ${body.id}`);
}

setInterval(updatePhysics, 16.67);
```

