  return (
    <div className="responsive-ui">
      <h1>Responsive UI</h1>
      <p>Width: {width}</p>
      <p>Height: {height}</p>

      {isMobile && <p>This is a mobile device.</p>}
      {!isMobile && <p>This is a desktop device.</p>}
