### Reconnection Logic with Exponential Backoff

Implementing reconnection logic with exponential backoff can help manage transient network issues more effectively. Here's an example of how you can do this:

#### Client-Side Reconnection Logic

```javascript
const WebSocket = require('ws');

class WebSocketClient {
  constructor(url) {
    this.url = url;
    this.socket = null;
    this.reconnectAttempts = 0;
    this.maxReconnectAttempts = 5;
    this.reconnectDelay = 1000; // Initial delay in milliseconds
    this.exponentialBackoffFactor = 2;
  }

  connect() {
    this.socket = new WebSocket(this.url);

    this.socket.onopen = () => {
      console.log('WebSocket connection established');
      this.reconnectAttempts = 0; // Reset reconnect attempts on successful connection
    };

    this.socket.onclose = (event) => {
      console.log('WebSocket connection closed', event);
      this.handleClose(event);
    };

    this.socket.onerror = (error) => {
      console.error('WebSocket error:', error);
      this.socket.close();
    };
  }

  handleClose(event) {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      const delay = this.reconnectDelay * Math.pow(this.exponentialBackoffFactor, this.reconnectAttempts);
      console.log(`Attempting to reconnect in ${delay} ms`);
      setTimeout(() => {
        this.connect();
        this.reconnectAttempts++;
      }, delay);
    } else {
      console.error('Max reconnection attempts reached. Giving up.');
    }
  }

  send(message) {
    if (this.socket.readyState === WebSocket.OPEN) {
      this.socket.send(JSON.stringify(message));
    } else {
      console.error('WebSocket is not open. Message not sent.');
    }
  }
}

