const redis = require('redis');
const client = redis.createClient();

class Matchmaker {
  constructor() {
    this.client = client;
  }

  async addPlayerToCache(playerId, rating, region) {
    await this.client.zadd('players', rating, playerId);
    await this.client.hset(`player:${playerId}`, 'rating', rating);
    await this.client.hset(`player:${playerId}`, 'region', region);
  }

  async findBestMatch(players) {
    let bestScore = 0;
    let bestPair = null;

    for (let i = 0; i < players.length; i++) {
      for (let j = i + 1; j < players.length; j++) {
        const score = await this.calculateMatchmakingScore(players[i], players[j]);
        if (score > bestScore) {
          bestScore = score;
          bestPair = [players[i], players[j]];
        }
      }
    }

    return bestPair;
  }

  async calculateMatchmakingScore(player1Id, player2Id) {
    const player1 = await this.getPlayerDetails(player1Id);
    const player2 = await this.getPlayerDetails(player2Id);

    const rating1 = player1.rating;
    const rating2 = player2.rating;
    const region1 = player1.region;
    const region2 = player2.region;

    const ratingDifference = Math.abs(rating1 - rating2);
    const regionScore = region1 === region2 ? 1 : 0;

    const combinedScore = (1 / (1 + ratingDifference / 400)) * regionScore;

    return combinedScore;
  }

  async getPlayerDetails(playerId) {
    const playerData = await this.client.hgetall(`player:${playerId}`);
    return {
      id: playerId,
      rating: parseInt(playerData.rating),
      region: playerData.region
    };
  }
}

