  setTimeout(() => {
    connection.close();
    process.exit(0);
  }, 500);
}

setupRabbitMQ();
```

#### Microservice 2: Receiver

This microservice will listen for matchmaking requests and process them.

```javascript
const amqp = require('amqplib');

async function setupRabbitMQ() {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  const queue = 'matchmaking_queue';
  await channel.assertQueue(queue, { durable: false });

  channel.consume(queue, (msg) => {
    if (msg !== null) {
      const matchmakingRequest = JSON.parse(msg.content.toString());
      console.log(`Received matchmaking request: ${JSON.stringify(matchmakingRequest)}`);
      // Process the matchmaking request here
      channel.ack(msg);
    }
  }, { noAck: false });

  console.log('Waiting for matchmaking requests...');
}

setupRabbitMQ();
```

### Explanation

1. **Connecting to RabbitMQ**: Both microservices connect to the RabbitMQ server using `amqp.connect('amqp://localhost')`.
2. **Creating a Queue**: The `assertQueue` method ensures that the queue exists.
3. **Sending a Message**: The sender microservice sends a matchmaking request to the queue using `sendToQueue`.
4. **Receiving a Message**: The receiver microservice listens for messages on the queue using `consume`. When a message is received, it processes the matchmaking request and acknowledges the message using `channel.ack`.

### Running the Microservices

