  min: 5,  // Minimum number of idle connections in the pool
  idleTimeoutMillis: 30000, // Close connections after 30 seconds of inactivity
  connectionTimeoutMillis: 30000, // Wait 30 seconds for a connection to become available
  maxUses: 100, // Close connections after 100 uses
});

