```javascript
const crypto = require('crypto');
const cryptoJS = require('crypto-js');

const secretKey = 'your-256-bit-secret-key'; // Ensure this is a 256-bit key

function encryptData(data) {
  const cipher = crypto.createCipheriv('aes-256-cbc', secretKey, crypto.randomBytes(16));
  let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

function decryptData(encryptedData) {
  const iv = encryptedData.slice(0, 32); // First 32 characters are the IV
  const encrypted = encryptedData.slice(32); // Remaining characters are the encrypted data
  const decipher = crypto.createDecipheriv('aes-256-cbc', secretKey, iv);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return JSON.parse(decrypted);
}
```

