```

### Step 2: Create a Custom WebSocket Connection Function

Create a custom function that handles WebSocket connections and retries. This function will be used in your Cypress tests.

```javascript
const WebSocket = require('ws');
const axiosRetry = require('axios-retry');

function connectWebSocket(url, options = {}, retries = 3, retryDelay = 1000) {
  return new Promise((resolve, reject) => {
    const connect = () => {
      const ws = new WebSocket(url, options);

      ws.on('open', () => {
        resolve(ws);
      });

      ws.on('error', (error) => {
        if (retries > 0) {
          setTimeout(() => {
            connect();
          }, retryDelay);
        } else {
          reject(error);
        }
      });

      ws.on('close', () => {
        if (retries > 0) {
          setTimeout(() => {
            connect();
          }, retryDelay);
        } else {
          reject(new Error('WebSocket connection closed'));
        }
      });
    };

    connect();
  });
}
```

