  private static final float CORRECTION_INTERVAL = 0.5f; // 500 ms correction interval
  private static final float SMOOTHING_FACTOR = 0.1f; // Smoothing factor for exponential smoothing

  private float estimatedDelay = 0.0f;

  public static void compensate(float[] data, float serverDelay) {
    LagCompensation compensator = new LagCompensation();
    long startTime = System.nanoTime(); // Use nanoTime for higher precision
    // Simulate some work here
    long endTime = System.nanoTime();
    float elapsed = (endTime - startTime) / 1000000000.0f; // Convert nanoseconds to seconds

    // Update the estimated delay using exponential smoothing
    compensator.updateEstimatedDelay(serverDelay);

