    float correctedState = compensator.correctState(predictedState, elapsed, serverDelay);

    // Print the results
    System.out.println("Original data: " + Arrays.toString(data));
    System.out.println("Predicted state: " + predictedState);
    System.out.println("Corrected state: " + correctedState);
  }

