  }

  private float correctState(float predictedState, float elapsed, float serverDelay) {
    // Simulate server correction with delay
    float serverState = predictedState + (float) Math.sin(elapsed + serverDelay); // Example correction logic
    return interpolate(predictedState, serverState, elapsed, serverDelay);
  }

  private float interpolate(float predictedState, float serverState, float elapsed, float serverDelay) {
    // Linear interpolation with delay compensation
    float alpha = elapsed / (CORRECTION_INTERVAL + estimatedDelay);
    return (1 - alpha) * predictedState + alpha * serverState;
  }

  private void updateEstimatedDelay(float serverDelay) {
    // Exponential smoothing to estimate the delay
    estimatedDelay = (1 - SMOOTHING_FACTOR) * estimatedDelay + SMOOTHING_FACTOR * serverDelay;
