  const connection = await amqp.connect('amqp://admin:admin@localhost:5672');
  const channel = await connection.createChannel();

  // Declare the exchange
  await channel.assertExchange('matchmaking-exchange', 'direct', { durable: true });

  // Declare the queue
  await channel.assertQueue('matchmaking-queue', { durable: true });

  // Bind the queue to the exchange
  await channel.bindQueue('matchmaking-queue', 'matchmaking-exchange', 'matchmaking-routing-key');

  console.log('RabbitMQ setup complete');
}

setupRabbitMQ().catch(console.error);
