    this.state = {
      position: { x: 0, y: 0 },
      velocity: { x: 0, y: 0 }
    };
    this.socket = socket;
  }

  reconcileClientState(clientState) {
    // Reconcile client-side state with server-side state
    this.state.position.x = clientState.position.x;
    this.state.position.y = clientState.position.y;
    this.state.velocity.x = clientState.velocity.x;
    this.state.velocity.y = clientState.velocity.y;

    // Send corrected state back to the client
    this.socket.emit('reconcileState', this.state);
  }
}
```

