Handling WebRTC disconnections and automatically switching to WebSocket involves detecting when the WebRTC connection fails and then establishing a WebSocket connection as a fallback. Here's a step-by-step guide to achieve this:

### Step 1: Set Up WebRTC Connection

First, set up the WebRTC connection and handle the necessary events.

### Step 2: Detect WebRTC Disconnections

Detect when the WebRTC connection fails by listening to the `iceConnectionState` changes.

### Step 3: Establish WebSocket Connection

Establish a WebSocket connection as a fallback when the WebRTC connection fails.

### Step 4: Manage Message Routing

Route messages through the active connection (WebRTC or WebSocket).

### Example Implementation

Here's a complete example that demonstrates these steps:

```javascript
class CommunicationManager {
  constructor(websocketUrl) {
    this.pc = new RTCPeerConnection({
      iceServers: [
        { urls: 'stun:stun.l.google.com:19302' },
        { urls: 'turn:your-turn-server.com', username: 'your-username', credential: 'your-password' }
      ]
    });
    this.dataChannel = null;
    this.websocket = null;
    this.websocketUrl = websocketUrl;
    this.isWebRtcConnected = false;
    this.isWebSocketConnected = false;
  }

  start() {
    this.setupWebRtc();
    this.setupWebSocket();
  }

  setupWebRtc() {
    this.pc.oniceconnectionstatechange = this.handleIceConnectionStateChange.bind(this);
    this.pc.ondatachannel = this.handleDataChannel.bind(this);

    this.dataChannel = this.pc.createDataChannel('game-data-channel', {
      ordered: true,
      maxRetransmits: 0
    });

    this.dataChannel.onopen = () => {
      this.isWebRtcConnected = true;
      console.log('WebRTC data channel opened');
    };

    this.dataChannel.onclose = () => {
      this.isWebRtcConnected = false;
      console.log('WebRTC data channel closed');
      this.fallbackToWebSocket();
    };

    this.dataChannel.onmessage = (event) => {
      console.log('Received WebRTC message:', event.data);
    };

    this.pc.createOffer().then(offer => {
      return this.pc.setLocalDescription(offer);
    }).then(() => {
      // Send the offer to the other peer
      this.sendOfferToPeer(this.pc.localDescription);
    }).catch(error => {
      console.error('Error creating offer:', error);
    });
  }

  setupWebSocket() {
    this.websocket = new WebSocket(this.websocketUrl);

    this.websocket.onopen = () => {
      this.isWebSocketConnected = true;
      console.log('WebSocket connected');
    };

    this.websocket.onclose = () => {
      this.isWebSocketConnected = false;
      console.log('WebSocket disconnected');
    };

    this.websocket.onmessage = (event) => {
      console.log('Received WebSocket message:', event.data);
    };
  }

  handleIceConnectionStateChange() {
    if (this.pc.iceConnectionState === 'disconnected' || this.pc.iceConnectionState === 'failed') {
      this.isWebRtcConnected = false;
      console.log('WebRTC connection failed');
      this.fallbackToWebSocket();
    }
  }

  handleDataChannel(event) {
    this.dataChannel = event.channel;
    this.dataChannel.onopen = () => {
      this.isWebRtcConnected = true;
      console.log('WebRTC data channel opened');
    };
  }

  fallbackToWebSocket() {
    if (!this.isWebSocketConnected) {
      console.log('Falling back to WebSocket');
      this.websocket = new WebSocket(this.websocketUrl);
      this.websocket.onopen = () => {
        this.isWebSocketConnected = true;
        console.log('WebSocket connected');
      };
    }
  }

