### Step-by-Step Guide

1. **Extract the IP Address from the Request**:
   - The `req` object passed to the `connection` event handler contains the IP address of the client connecting to the WebSocket server.

2. **Check the IP Address Against the Whitelist**:
   - Compare the extracted IP address with the list of whitelisted IPs.
   - If the IP address is not in the whitelist, close the connection.

3. **Handle Valid Connections**:
   - If the IP address is in the whitelist, proceed with handling the WebSocket connection.

### Example Implementation

Here's a complete example demonstrating how to implement IP whitelisting:

```javascript
const WebSocket = require('ws');

// Define the whitelist of allowed IP addresses
const whitelist = ['192.168.1.100', '192.168.1.200'];

// Create a WebSocket server
const wss = new WebSocket.Server({ port: 8080 });

// Middleware to check IP address against the whitelist
function checkWhitelist(ipAddress) {
  return whitelist.includes(ipAddress);
}

// Handle incoming WebSocket connections
wss.on('connection', (ws, req) => {
  // Extract the IP address from the request
  const ipAddress = req.connection.remoteAddress;

  // Check if the IP address is in the whitelist
  if (!checkWhitelist(ipAddress)) {
    console.log(`Connection attempt from non-whitelisted IP: ${ipAddress}`);
    ws.close(403, 'Forbidden');
    return;
  }

  // Proceed with handling the WebSocket connection
  console.log(`Connection established from whitelisted IP: ${ipAddress}`);

  // Handle messages
  ws.on('message', (message) => {
    console.log(`Received message: ${message}`);
    // Process the message
  });

  // Handle errors
  ws.on('error', (error) => {
    console.error(`WebSocket error: ${error.message}`);
  });

  // Handle close
  ws.on('close', () => {
    console.log(`Connection closed from IP: ${ipAddress}`);
  });
});

// Start the WebSocket server
console.log('WebSocket server started on ws://localhost:8080');
```

### Explanation

1. **Define the Whitelist**:
