    this.currentState = null;
    this.serverState = null;
    this.lastUpdateTimestamp = Date.now();
  }

  compensate(lag) {
    this.lag = lag;
    this.updatePredictedState();
  }

  updatePredictedState() {
    const currentTime = Date.now();
    const deltaTime = (currentTime - this.lastUpdateTimestamp) / 1000;

    if (this.serverState) {
      this.previousState = this.currentState;
      this.currentState = this.serverState;
      this.lastUpdateTimestamp = currentTime;
    }

    if (this.previousState && this.currentState) {
      // Linear interpolation between previous and current states
      const alpha = deltaTime / 0.1; // Adjust the smoothing factor as needed
      this.interpolateState(alpha);
    }
  }

  interpolateState(alpha) {
    this.currentState = {
      x: this.previousState.x + (this.currentState.x - this.previousState.x) * alpha,
      y: this.previousState.y + (this.currentState.y - this.previousState.y) * alpha,
    };
  }

  applyServerState(serverState) {
    this.serverState = serverState;
    this.updatePredictedState();
  }

  getCurrentState() {
    return this.currentState || this.previousState || { x:  0, y: 0 };
  }
}

module.exports = LagCompensation;
```

