  switch (pc.connectionState) {
    case 'connected':
      console.log('WebRTC connection established');
      break;
    case 'disconnected':
      console.log('WebRTC connection lost');
      // Attempt to reconnect or use fallback mechanisms
      break;
    case 'failed':
      console.log('WebRTC connection failed');
      // Handle failure and retry or use fallback mechanisms
      break;
  }
};

