       return pc.createAnswer();
     }).then((answer) => {
       return pc.setLocalDescription(answer);
     }).then(() => {
       // Send the answer to the other peer
       sendAnswerToOtherPeer(pc.localDescription);
     }).catch((error) => {
       console.error('Error handling remote offer:', error);
     });
