let authoritativeState = {
  position: { x: 0, y: 0 },
  velocity: { x: 0, y: 0 }
};

function handleAction(action) {
  // Apply the action to the authoritative state
  switch (action.type) {
    case 'move':
      authoritativeState.position.x += action.dx;
      authoritativeState.position.y += action.dy;
      break;
    // Add other actions as needed
  }

  // Send the updated state to the client
  dc.send(JSON.stringify({ type: 'stateUpdate', state: authoritativeState }));
}

function handleStateUpdate(state) {
  // Update the client's state to match the authoritative state
  predictedState = state;

  // Optionally, interpolate or extrapolate to smooth the transition
  interpolateState(predictedState);
}

function handleCorrection(correction) {
  // Apply the correction to the client's state
  predictedState = correction;

  // Optionally, interpolate or extrapolate to smooth the transition
  interpolateState(predictedState);
}

function interpolateState(targetState) {
  // Interpolate between the current state and the target state
  const currentTimestamp = Date.now();
  const targetTimestamp = currentTimestamp + 100; // Adjust based on desired smoothing duration

  const lerp = (a, b, t) => a + (b - a) * t;

  const lerpPosition = (currentPos, targetPos, t) => ({
    x: lerp(currentPos.x, targetPos.x, t),
    y: lerp(currentPos.y, targetPos.y, t)
  });

  const lerpVelocity = (currentVel, targetVel, t) => ({
    x: lerp(currentVel.x, targetVel.x, t),
    y: lerp(currentVel.y, targetVel.y, t)
  });

  const interpolate = (t) => ({
    position: lerpPosition(predictedState.position, targetState.position, t),
    velocity: lerpVelocity(predictedState.velocity, targetState.velocity, t)
  });

  const t = Math.min(1, (Date.now() - currentTimestamp) / (targetTimestamp - currentTimestamp));
  predictedState = interpolate(t);
}

