class LagCompensation {
  constructor() {
    this.interpolationDelay = 100; // ms
    this.extrapolationLimit = 500; // ms
    this.lastServerState = null;
    this.lastDeltaTime = 0;
  }

  // Adaptive interpolation delay based on network conditions
  updateInterpolationDelay(avgPing) {
    if (avgPing < 50) {
      this.interpolationDelay = 50; // Lower delay for low-latency networks
    } else if (avgPing < 100) {
      this.interpolationDelay = 75; // Moderate delay for mid-latency networks
    } else {
      this.interpolationDelay = 100; // Higher delay for high-latency networks
    }
  }

  // Cubic interpolation for smoother transitions
  interpolate(playerState, serverState, deltaTime) {
    const alpha = Math.min(deltaTime / this.interpolationDelay, 1);
    const beta = 1 - alpha;
    return {
      x: playerState.x * beta + serverState.x * alpha,
      y: playerState.y * beta + serverState.y * alpha,
    };
  }

  // Predictive extrapolation based on historical data
  extrapolate(playerState, deltaTime) {
    if (!this.lastServerState) {
      this.lastServerState = playerState;
    }
    const velocityX = (playerState.x - this.lastServerState.x) / this.lastDeltaTime;
    const velocityY = (playerState.y - this.lastServerState.y) / this.lastDeltaTime;
    this.lastServerState = playerState;
    this.lastDeltaTime = deltaTime;
    return {
      x: playerState.x + velocityX * deltaTime,
      y: playerState.y + velocityY * deltaTime,
    };
  }
}

