Ensuring a stable WebSocket connection during intense gameplay involves several best practices and techniques to handle network conditions, manage reconnections, and optimize data transmission. Here are some strategies to help maintain a stable WebSocket connection:

### 1. Heartbeat Mechanism
Implement a heartbeat mechanism to periodically check the connection status and detect disconnections early.

```javascript
class WebSocketManager {
  constructor(url) {
    this.url = url;
    this.socket = null;
    this.reconnectInterval = 5000; // milliseconds
    this.heartbeatInterval = 10000; // milliseconds
    this.isAlive = true;
  }

  connect() {
    this.socket = new WebSocket(this.url);
    this.socket.addEventListener('open', this.onOpen.bind(this));
    this.socket.addEventListener('close', this.onClose.bind(this));
    this.socket.addEventListener('error', this.onError.bind(this));
    this.socket.addEventListener('message', this.onMessage.bind(this));
  }

  onOpen() {
    console.log('WebSocket connection established');
    this.startHeartbeat();
  }

  onClose(event) {
    console.log('WebSocket connection closed', event);
    this.stopHeartbeat();
    this.reconnect();
  }

  onError(event) {
    console.error('WebSocket error', event);
  }

  onMessage(event) {
    console.log('Received message:', event.data);
    // Handle incoming messages
  }

  startHeartbeat() {
    this.isAlive = true;
    this.socket.addEventListener('ping', () => {
      this.isAlive = true;
    });

    this.heartbeatIntervalId = setInterval(() => {
      if (this.isAlive) {
        this.isAlive = false;
        this.socket.ping('');
      } else {
        this.socket.close();
      }
    }, this.heartbeatInterval);
  }

  stopHeartbeat() {
    clearInterval(this.heartbeatIntervalId);
  }

  reconnect() {
    setTimeout(() => {
      this.connect();
    }, this.reconnectInterval);
  }
}

