      console.log('ComponentA received event:', data);
    };

    EventManager.subscribe('eventA', handleEvent);

    return () => {
      EventManager.unsubscribe('eventA', handleEvent);
    };
  }, []);

  return (
    <View>
      <Text>Component A</Text>
    </View>
  );
};

export default ComponentA;
```

#### ComponentB.js
