import React, { useEffect } from 'react';
import { View, Text } from 'react-native';
import EventManager from '../EventManager';

const ComponentB = () => {
  useEffect(() => {
    const handleEvent = (data) => {
      console.log('ComponentB received event:', data);
    };

    EventManager.subscribe('eventB', handleEvent);

    return () => {
      EventManager.unsubscribe('eventB', handleEvent);
    };
  }, []);

  return (
    <View>
      <Text>Component B</Text>
    </View>
  );
};

export default ComponentB;
```

### Using Context for Event Management

Another approach is to use React Context to manage event subscriptions and emissions. This can be particularly useful if you have a lot of components that need to interact with the same events.

#### EventContext.js
```javascript
import React, { createContext, useContext, useState, useEffect } from 'react';

const EventContext = createContext();

const EventProvider = ({ children }) => {
  const [events, setEvents] = useState({});

  const subscribe = (eventName, callback) => {
    if (!events[eventName]) {
      setEvents((prevEvents) => ({
        ...prevEvents,
        [eventName]: new Set(),
      }));
    }
    events[eventName].add(callback);
  };

  const unsubscribe = (eventName, callback) => {
    if (events[eventName]) {
      events[eventName].delete(callback);
    }
  };

  const emit = (eventName, data) => {
    if (events[eventName]) {
      events[eventName].forEach((callback) => {
        callback(data);
      });
    }
  };

  return (
    <EventContext.Provider value={{ subscribe, unsubscribe, emit }}>
      {children}
    </EventContext.Provider>
  );
};

export { EventProvider, EventContext };
```

#### Usage in Components

Now, you can use the `EventContext` in your components to subscribe and unsubscribe from events.

#### ComponentA.js
```javascript
import React, { useEffect, useContext } from 'react';
import { View, Text } from 'react-native';
import { EventContext } from '../EventContext';

const ComponentA = () => {
  const { subscribe, unsubscribe, emit } = useContext(EventContext);

  useEffect(() => {
    const handleEvent = (data) => {
      console.log('ComponentA received event:', data);
    };

    subscribe('eventA', handleEvent);

    return () => {
      unsubscribe('eventA', handleEvent);
    };
  }, [subscribe, unsubscribe]);

  return (
    <View>
      <Text>Component A</Text>
    </View>
  );
};

export default ComponentA;
```

#### ComponentB.js
