import { View, Text } from 'react-native';
import { EventContext } from '../EventContext';

const ComponentB = () => {
  const { subscribe, unsubscribe, emit } = useContext(EventContext);

  useEffect(()_ => {
    const handleEvent = (data) => {
      console.log('ComponentB received event:', data);
    };

    subscribe('eventB', handleEvent);

    return () => {
