const key = 'leaderboard-data/leaderboard.json.gz';
const data = JSON.stringify({ /* your leaderboard data */ });

uploadCompressedData(bucketName, key, data)
  .then(() => console.log('Data uploaded successfully'))
  .catch(err => console.error('Error uploading data:', err));
```

