  try {
    // Update the leaderboard in Redis
    await redis.zadd('leaders', leader.score, leader.name);
  } catch (error) {
    console.error('Error updating leaderboard:', error);
  }
}

// Update the leaderboard for multiple leaders
async function updateLeaders(leaders) {
  try {
