### Step 2: Create Producer and Consumer Pipelines

Next, you need to create producer and consumer pipelines for each peer.

#### Server-Side Code

```javascript
const io = require('socket.io')(server);

io.on('connection', async (socket) => {
  console.log('Client connected:', socket.id);

  const { worker, router } = await setupMediasoup();

  const transportOptions = {
    comedia: true,
    rtcpMux: true,
  };

  const transport = await router.createTransport(transportOptions);

  socket.emit('transport', {
    id: transport.id,
    iceParameters: transport.iceParameters,
    iceCandidates: transport.iceCandidates,
    dtlsParameters: transport.dtlsParameters,
  });

  socket.on('produce', async (data) => {
    const { kind, rtpParameters, appData } = data;

    const producer = await transport.produce({
      kind,
      rtpParameters,
      appData,
    });

    socket.emit('producer', {
      id: producer.id,
    });

    producer.on('transportclose', () => {
      producer.close();
    });
  });

  socket.on('consume', async (data) => {
    const { producerId, rtpCapabilities } = data;

    const consumer = await transport.consume({
      id: producerId,
      rtpCapabilities,
    });

    socket.emit('consumer', {
      id: consumer.id,
      kind: consumer.kind,
      rtpParameters: consumer.rtpParameters,
    });

    consumer.on('transportclose', () => {
      consumer.close();
    });
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
    transport.close();
  });
});
