  setupMediasoup();
}
```

### 2. **Distribute Participants Across Routers**
When a new participant joins, assign them to a router that has the least number of participants.

```javascript
function getLeastLoadedRouter() {
  let leastLoadedRouter = routers[0];
  let minParticipants = Infinity;

  for (const router of routers) {
    const participants = router.getProducers().length;
    if (participants < minParticipants) {
      minParticipants = participants;
      leastLoadedRouter = router;
    }
  }

  return leastLoadedRouter;
}
```

