```javascript
class VoiceChatManager {
  constructor() {
    this.peerConnections = new WeakMap();
    this.mediaStreams = new WeakMap();
  }

  addPeerConnection(peerId, peerConnection) {
    this.peerConnections.set(peerId, peerConnection);
    this.setupPeerConnectionEvents(peerConnection);
