  removePeerConnection(peerId) {
    const peerConnection = this.peerConnections.get(peerId);
    if (peerConnection) {
      peerConnection.close();
      this.peerConnections.delete(peerId);
    }
  }

  addMediaStream(peerId, mediaStream) {
    this.mediaStreams.set(peerId, mediaStream);
  }

  removeMediaStream(peerId) {
    const mediaStream = this.mediaStreams.get(peerId);
    if (mediaStream) {
      mediaStream.getTracks().forEach(track => track.stop());
      this.mediaStreams.delete(peerId);
    }
  }

  getPeerConnection(peerId) {
    return this.peerConnections.get(peerId);
  }

  getMediaStream(peerId) {
    return this.mediaStreams.get(peerId);
  }

  setupPeerConnectionEvents(peerConnection) {
    peerConnection.addEventListener('iceconnectionstatechange', () => {
      console.log(`ICE connection state changed to ${peerConnection.iceConnectionState}`);
      if (peerConnection.iceConnectionState === 'disconnected' || peerConnection.iceConnectionState === 'failed') {
        this.removePeerConnection(peerConnection.peerId);
      }
    });

    peerConnection.addEventListener('track', (event) => {
      console.log('New track received');
      const mediaStream = event.streams[0];
      this.addMediaStream(peerConnection.peerId, mediaStream);
    });

    peerConnection.addEventListener('negotiationneeded', () => {
      console.log('Negotiation needed');
      // Handle negotiation needed event
    });

    peerConnection.addEventListener('connectionstatechange', () => {
      console.log(`Connection state changed to ${peerConnection.connectionState}`);
      if (peerConnection.connectionState === 'disconnected' || peerConnection.connectionState === 'failed') {
        this.removePeerConnection(peerConnection.peerId);
      }
    });
  }
}
```

### Explanation

1. **WeakMap Usage**:
   - `WeakMap` is used for `peerConnections` and `mediaStreams` to allow for efficient garbage collection.

2. **Setup Peer Connection Events**:
   - `setupPeerConnectionEvents` method is added to handle various events on the `RTCPeerConnection` object, such as `iceconnectionstatechange`, `track`, and `negotiationneeded`.

3. **Retrieve Methods**:
   - `getPeerConnection` and `getMediaStream` methods are added to retrieve peer connections and media streams by `peerId`.

4. **Error Handling and Logging**:
   - Basic logging is included to track state changes and handle disconnections.

By implementing these changes, your `VoiceChatManager` will be more efficient, maintainable, and robust in handling multiple peer connections and media streams.

