  }

  resetEvent() {
    // Logic to reset the event
    console.log(`[${new Date().toISOString()}] Resetting event ${this.eventId}`);
  }

  async getCachedEvent() {
    try {
      const cachedEvent = await client.get(this.cacheKey);
      return cachedEvent ? JSON.parse(cachedEvent) : null;
    } catch (err) {
      console.error(`[${new Date().toISOString()}] Error retrieving cached event:`, err);
      return null;
    }
  }

  async cacheEvent() {
    try {
      const eventInfo = {
        eventId: this.eventId,
        startTime: this.startTime,
        endTime: this.endTime
      };
      await client.set(this.cacheKey, JSON.stringify(eventInfo), 'EX', 3600); // Cache for 1 hour
      console.log(`[${new Date().toISOString()}] Event ${this.eventId} cached`);
    } catch (err) {
      console.error(`[${new Date().toISOString()}] Error caching event:`, err);
    }
  }

  async removeCachedEvent() {
    try {
      await client.del(this.cacheKey);
      console.log(`[${new Date().toISOString()}] Event ${this.eventId} removed from cache`);
    } catch (err) {
      console.error(`[${new Date().toISOString()}] Error removing cached event:`, err);
    }
  }
