const paymentGateways = {
  stripe: {
    createCharge: async (amount, source) => {
      try {
        const charge = await stripe.charges.create({
          amount,
          currency: 'usd',
          source,
          description: 'Test charge'
        });
        return { success: true, data: charge };
      } catch (err) {
