          return { success: false, error: 'Expired card token', details: err };
        }
        return { success: false, error: 'Payment processing failed', details: err };
      }
    }
  },
  paypal: {
    createPayment: async (amount) => {
      try {
        const payment = await paypal.payment.create({
          intent: 'sale',
          payer: {
            payment_method: 'paypal'
          },
          transactions: [
            {
              amount: {
                currency: 'USD',
                total: amount
              }
            }
          ]
        });
        return { success: true, data: payment };
      } catch (err) {
        return { success: false, error: 'Payment processing failed', details: err };
      }
    }
  }
};

// Generic payment processing function
async function processPayment(gatewayName, amount, source) {
  const gateway = paymentGateways[gatewayName];
  if (!gateway) {
    throw new Error(`Gateway ${gatewayName} not found`);
  }

  let result;
  if (gatewayName === 'stripe') {
    result = await gateway.createCharge(amount, source);
  } else if (gatewayName === 'paypal') {
    result = await gateway.createPayment(amount);
  }

  if (!result.success) {
    console.error(result.error, result.details);
    throw new Error(result.error);
  }

  return result.data;
}

// Example usage
