    if (data.type === 'update_balance') {
      const { userId, amount } = data;
      const currentBalance = walletBalances.get(userId) || 0;
      const newBalance = currentBalance + amount;
      updateWalletBalance(userId, newBalance);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });

  // Heartbeat mechanism
  const heartbeatInterval = 30000; // 30 seconds
  const heartbeatTimeout = 60000; // 60 seconds

  let heartbeatTimer;
  let heartbeatTimeoutTimer;

  function sendHeartbeat() {
    ws.ping('', false, true);
  }

  function resetHeartbeat() {
    clearTimeout(heartbeatTimer);
    clearTimeout(heartbeatTimeoutTimer);

    heartbeatTimer = setTimeout(sendHeartbeat, heartbeatInterval);
    heartbeatTimeoutTimer = setTimeout(() => {
      console.log('Heartbeat timeout, closing connection');
      ws.close();
    }, heartbeatTimeout);
  }

  ws.on('pong', () => {
    resetHeartbeat();
  });

  resetHeartbeat();
});

// Example usage
setTimeout(() => {
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify({ type: 'initial_balance', userId: 1, balance: 1000 }));
    }
  });
}, 5000);
```

### Explanation

