const stripe = require('stripe')('my_secret_key');

async function processLogsAndPaymentsInBatches() {
  const paymentMap = new Map();

  // Fetch all payments and store them in a map for quick lookup
  let payments = await stripe.charges.list({ limit: 100 });
  while (true) {
    payments.data.forEach(payment => paymentMap.set(payment.id, payment));
    if (!payments.has_more) break;
    payments = await stripe.charges.list({ limit: 100, starting_after: payments.data[payments.data.length - 1].id });
