async function processLogsAndPaymentsInBatches() {
  const paymentMap = new Map();

  // Fetch all payments and store them in a map for quick lookup
  async function fetchAllPayments() {
    let payments = await stripe.charges.list({ limit: 100 });
    while (true) {
      payments.data.forEach(payment => paymentMap.set(payment.id, payment));
      if (!payments.has_more) break;
      try {
        payments = await stripe.charges.list({ limit: 100, starting_after: payments.data[payments.data.length - 1].id });
      } catch (error) {
        if (error.type === 'rate_limit_error') {
          console.log('Rate limit error, retrying...');
          await delay(2 ** retryCount * 1000); // Exponential backoff
          payments = await stripe.charges.list({ limit: 100, starting_after: payments.data[payments.data.length - 1].id });
        } else {
          throw error;
        }
      }
    }
  }

  // Fetch all logs and compare with payments
  async function fetchAllLogs() {
    let logs = await stripe.logs.list({ limit: 100 });
    while (true) {
      logs.data.forEach(log => {
        const payment = paymentMap.get(log.object.id);
        if (payment) {
          console.log(`Log ${log.id} matches payment ${payment.id}`);
        } else {
          console.log(`Log ${log.id} does not match any payment`);
        }
      });
      if (!logs.has_more) break;
      try {
        logs = await stripe.logs.list({ limit: 100, starting_after: logs.data[logs.data.length - 1].id });
      } catch (error) {
        if (error.type === 'rate_limit_error') {
          console.log('Rate limit error, retrying...');
          await delay(2 ** retryCount * 1000); // Exponential backoff
          logs = await stripe.logs.list({ limit: 100, starting_after: logs.data[logs.data.length - 1].id });
        } else {
          throw error;
        }
      }
    }
  }

  let retryCount = 0;

  try {
    await fetchAllPayments();
    await fetchAllLogs();
  } catch (error) {
    console.error('An error occurred:', error);
  }
}

processLogsAndPaymentsInBatches();
```

### Explanation

1. **Custom Delay Function:**
   - A custom `delay` function is used to pause execution for a specified amount of time.

2. **Exponential Backoff:**
   - When a rate limit error occurs, the script waits for an exponentially increasing amount of time before retrying the request. This helps avoid hitting the rate limit repeatedly.

3. **Error Handling:**
   - The script catches rate limit errors and retries the request after a delay. Other types of errors are re-thrown to be handled elsewhere.

### Additional Considerations

- **Rate Limit Information:**
  - Stripe API responses include headers like `Stripe-Rate-Limit` and `Stripe-Rate-Limit-Remaining` that can provide information about the rate limit status. You can use this information to dynamically adjust the delay times.

- **Logging:**
  - Add logging to track the number of retries and the delay times to help diagnose and optimize the script's performance.

By implementing these strategies, you can handle rate limits more gracefully and ensure that your script runs efficiently even with large datasets.

